# Udemy API Integration
import requests

UDEMY_CLIENT_ID = "EEr58ok9yozgyDTzfc3iim9RccHmrmFaBo8mpVk2"
UDEMY_CLIENT_SECRET = "your_secret"

def search_udemy_courses(keyword):
    """Search for courses on Udemy"""
    auth = requests.post(
        "https://www.udemy.com/oauth-2/token/",
        data={
            "client_id": UDEMY_CLIENT_ID,
            "client_secret": UDEMY_CLIENT_SECRET,
            "grant_type": "client_credentials"
        }
    )
    token = auth.json().get("access_token")

    response = requests.get(
        "https://www.udemy.com/api-2.0/courses/",
        headers={"Authorization": f"Bearer {token}"},
        params={"search": keyword, "page_size": 50}
    )
    return response.json()

def get_course_trends():
    """Get trending course topics"""
    response = requests.get(
        "https://www.udemy.com/api-2.0/courses/trending/",
        headers={"Authorization": f"Bearer {token}"}
    )
    return response.json()
